let seq = 1000;
function make(p: Partial<Product> & { slug: string; name: string; brand: string; categorySlug: string; price: number; shortDescription: string }): Product {
  seq += 1;
  const [cf, ct, icon] = CAT_COLORS[p.categorySlug] ?? ["#334155", "#1e293b", "Package"];
  return {
    id: String(seq),
    model: "",
    code: `OC-${seq}`,
    type: "ortopedico",
    gtin: undefined,
    sizes: ["PP", "P", "M", "G", "GG"],
    oldPrice: undefined,
    installmentsMax: 12,
    availability: "em-estoque",
    stock: 20,
    rating: 4.5,
    reviewsCount: 15,
    badges: [] as Badge[],
    needsCompatibilityCheck: false,
    compatibility: [],
    specs: {},
    description: "Produto ortopédico de alta qualidade distribuído pela OrtoCenter. Consulte um profissional de saúde para indicação e medidas adequadas.",
    reviews: [
      { author: "Cliente", rating: 5, comment: "Produto excelente, entrega rápida.", date: "2026-06-15" },
      { author: "Profissional", rating: 4, comment: "Boa qualidade e bom custo-benefício.", date: "2026-05-20" },
    ],
    ...p,
    colorFrom: p.colorFrom ?? cf,
    colorTo: p.colorTo ?? ct,
    imageIcon: p.imageIcon ?? icon,
  } as Product;
}

