export const productBySlug = (slug: string) => products.find((p) => p.slug === slug);
export const productById = (id: string) => products.find((p) => p.id === id);

export const brands = Array.from(new Set(products.map((p) => p.brand))).sort();
export const maxPrice = Math.ceil(Math.max(...products.map((p) => p.price)) / 1000) * 1000;

export const featured = products.filter((p) => p.badges.includes("mais-vendido"));
export const novelties = products.filter((p) => p.badges.includes("novidade"));
export const offers = products.filter((p) => p.badges.includes("oferta"));